// Extraer y validar campos del payload del microservicio
const body = $input.first().json.body ?? $input.first().json;

const data = {
  call_db_id:        body.call_db_id ?? null,
  vapi_call_id:      body.vapi_call_id ?? null,
  business_id:       body.business_id ?? null,
  business_name:     body.business_name ?? 'Negocio desconocido',
  transcript:        body.transcript ?? '',
  duration_sec:      body.duration_sec ?? 0,
  transfer_whatsapp: body.transfer_whatsapp ?? null,
};

if (!data.call_db_id) throw new Error('call_db_id requerido');
if (!data.transcript) throw new Error('transcript vacío — no hay nada que analizar');

return [{ json: data }];

// Parsear la respuesta de GPT y preparar el update de Supabase
const analysis = $input.first().json;
const prevData = $('Validar payload').first().json;

let parsed;
try {
  const raw = analysis.content ?? analysis.text ?? JSON.stringify(analysis);
  parsed = JSON.parse(raw);
} catch {
  parsed = {
    summary: 'No se pudo analizar la transcripción.',
    outcome: 'error',
    sentiment: 'neutral',
    sentiment_score: 0,
    language_detected: 'es',
    key_topic: 'error análisis',
  };
}

return [{ json: { ...prevData, analysis: parsed } }];

// Solo enviar WhatsApp si hay número de transfer y el análisis es válido
const data = $input.first().json;

if (!data.transfer_whatsapp) {
  return [{ json: { skip_whatsapp: true, ...data } }];
}

const dur = data.duration_sec ? `${Math.round(data.duration_sec / 60)}min ${data.duration_sec % 60}s` : 'desconocida';
const icon = data.analysis.sentiment === 'positive' ? '😊' :
              data.analysis.sentiment === 'negative' ? '⚠️' : '📞';

const message = `${icon} *Llamada a ${data.business_name}*\n\n` +
  `*Resumen:* ${data.analysis.summary}\n` +
  `*Resultado:* ${data.analysis.outcome}\n` +
  `*Duración:* ${dur}\n` +
  `*Tema:* ${data.analysis.key_topic}\n\n` +
  `_ContaProNow — voz-agente_`;

return [{ json: { ...data, whatsapp_message: message } }];
